      "B": "$\\text{cis}-[\\text{Co}(\\text{en})_2\\text{Cl}_2]^+$",
      "C": "$[\\text{Co}(\\text{NH}_3)_4\\text{Cl}_2]^+$",
      "D": "$[\\text{Pt}(\\text{NH}_3)_2\\text{Cl}_2]$"
