    "question": "Q108. According to Crystal Field Theory (CFT), for an octahedral complex with $d^4$ configuration, pairing of electrons will occur to give a low-spin state ($t_{2g}^4 e_g^0$) when:",
    "options": {
      "A": "$\\Delta_o < P$",
      "B": "$\\Delta_o = 0$",
      "C": "$\\Delta_t = \\frac{4}{9} \\Delta_o$",
      "D": "$\\Delta_o > P$ (crystal field splitting exceeds electron pairing energy)"
    },
    "optionsList": [
      "$\\Delta_o < P$",
      "$\\Delta_o = 0$",
      "$\\Delta_t = \\frac{4}{9} \\Delta_o$",
      "$\\Delta_o > P$ (crystal field splitting exceeds electron pairing energy)"
    ],
    "correctAnswer": "D",
    "correctIndex": 3,
    "explanation": "1. CONCEPT & PRINCIPLE:\nCrystal field splitting ($\\Delta_o$) versus mean pairing energy ($P$) in octahedral complexes.\n\n2. GIVEN INFORMATION / DATA:\n$d^4$ metal ion in an octahedral ligand field.\n\n3. FORMULA / EQUATION:\nIf $\\Delta_o > P \\implies$ Low spin ($t_{2g}^4 e_g^0$); If $\\Delta_o < P \\implies$ High spin ($t_{2g}^3 e_g^1$).\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. In an octahedral complex, the degenerate $d$-orbitals split into lower-energy $t_{2g}$ (3 orbitals) and higher-energy $e_g$ (2 orbitals) separated by energy $\\Delta_o$.\n2. The first 3 electrons singly occupy the $t_{2g}$ orbitals with parallel spins ($t_{2g}^3$).\n3. For the 4th electron, two options exist: jump to higher energy $e_g$ orbital (costing $\\Delta_o$) or pair up in $t_{2g}$ (costing pairing energy $P$).\n4. If strong-field ligands are present such that $\\Delta_o > P$, pairing is energetically favored, forcing the 4th electron into $t_{2g}$ to yield the low-spin configuration $t_{2g}^4 e_g^0$.\n\n5. FINAL CONCLUSION:\n$\\Delta_o > P$ (crystal field splitting exceeds electron pairing energy)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nIf $\\Delta_o < P$, high spin $t_{2g}^3 e_g^1$ forms with maximum unpaired electrons.",
    "solutionStructured": {
      "concept": "Crystal field splitting ($\\Delta_o$) versus mean pairing energy ($P$) in octahedral complexes.",
      "given": "$d^4$ metal ion in an octahedral ligand field.",
      "formula": "If $\\Delta_o > P \\implies$ Low spin ($t_{2g}^4 e_g^0$); If $\\Delta_o < P \\implies$ High spin ($t_{2g}^3 e_g^1$).",
      "stepByStep": "1. In an octahedral complex, the degenerate $d$-orbitals split into lower-energy $t_{2g}$ (3 orbitals) and higher-energy $e_g$ (2 orbitals) separated by energy $\\Delta_o$.\n2. The first 3 electrons singly occupy the $t_{2g}$ orbitals with parallel spins ($t_{2g}^3$).\n3. For the 4th electron, two options exist: jump to higher energy $e_g$ orbital (costing $\\Delta_o$) or pair up in $t_{2g}$ (costing pairing energy $P$).\n4. If strong-field ligands are present such that $\\Delta_o > P$, pairing is energetically favored, forcing the 4th electron into $t_{2g}$ to yield the low-spin configuration $t_{2g}^4 e_g^0$.",
      "finalAnswer": "$\\Delta_o > P$ (crystal field splitting exceeds electron pairing energy)",
      "whyOtherOptionsWrong": "If $\\Delta_o < P$, high spin $t_{2g}^3 e_g^1$ forms with maximum unpaired electrons."
    },
